package com.lamggm.rospocket;
import android.view.*;import android.content.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class CompactDashboardTest {
 @Test public void watchResizeGestureUsesTheRenderedWatchPitch(){Context c=RuntimeEnvironment.getApplication();DashboardBoard b=new DashboardBoard(c);b.bind(DashboardLayout.defaults(),null);b.addCard("watch0","Watch0",new MetricCard(c),null);b.edit();b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());View handle=b.findViewWithTag("layout-resize:watch0");DashboardBoardTest.send(handle,0,20,20);DashboardBoardTest.send(handle,2,20,220);DashboardBoardTest.send(handle,1,20,220);assertEquals("200dp drag advances two compact row pitches",3,b.layout().get("watch0").height);}
 @Test public void oneByOneReadingsStayCompactIncludingGaugeAndBar(){Context ctx=RuntimeEnvironment.getApplication();DashboardBoard b=new DashboardBoard(ctx);DashboardLayout l=DashboardLayout.defaults();String[] modes={"number","gauge","bar","gauge"};for(int i=0;i<4;i++)l=l.display("watch"+i,new DashboardLayout.Display(modes[i],"data",0,100,"V"));b.bind(l,null);for(int i=0;i<4;i++)b.addCard("watch"+i,"Watch "+i,new MetricCard(ctx),null);b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());for(int i=0;i<4;i++){View c=b.findViewWithTag("dashboard-card:watch"+i);assertTrue("1x1 must not secretly reserve two rows: "+modes[i]+" height="+c.getHeight(),c.getHeight()<=124*ctx.getResources().getDisplayMetrics().density);assertEquals(1,b.layout().get("watch"+i).height);}}
}
